class _Parser:
    def __init__(self, text):
        self.text = text
        self.i = 0
        self.tok = None
        self.advance()

    def advance(self):
        t, n = self.text, len(self.text)
        i = self.i
        while i < n and t[i] in " \\t":
            i += 1
        if i >= n:
            self.tok = ("end", None, n)
            self.i = n
            return
        c = t[i]
        start = i
        if c.isascii() and (c.isdigit() or c == "."):
            while i < n and t[i].isascii() and t[i].isdigit():
                i += 1
            if i < n and t[i] == ".":
                i += 1
                while i < n and t[i].isascii() and t[i].isdigit():
                    i += 1
                text = t[start:i]
                if text == ".":
                    raise CalcError("unexpected character '.'", start)
                self.tok = ("num", float(text), start)
            else:
                self.tok = ("num", int(t[start:i]), start)
        elif c == "_" or (c.isascii() and c.isalpha()):
            while i < n and (t[i] == "_" or (t[i].isascii() and t[i].isalnum())):
                i += 1
            self.tok = ("name", t[start:i], start)
        elif t.startswith("**", i) or t.startswith("//", i):
            i += 2
            self.tok = ("op", t[start:i], start)
        elif c in "+-*/%(),":
            i += 1
            self.tok = ("op", c, start)
        else:
            raise CalcError(f"unexpected character {c!r}", start)
        self.i = i

    def is_op(self, *ops):
        return self.tok[0] == "op" and self.tok[1] in ops

    def fail(self):
        kind, val, pos = self.tok
        if kind == "end":
            raise CalcError("unexpected end of expression", pos)
        raise CalcError(f"unexpected token {val!r}", pos)

    def expect(self, op):
        if not self.is_op(op):
            self.fail()
        self.advance()

    def parse(self):
        node = self.expr()
        if self.tok[0] != "end":
            self.fail()
        return node

    def expr(self):
        node = self.term()
        while self.is_op("+", "-"):
            op, pos = self.tok[1], self.tok[2]
            self.advance()
            node = ("bin", op, pos, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.is_op("*", "/", "//", "%"):
            op, pos = self.tok[1], self.tok[2]
            self.advance()
            node = ("bin", op, pos, node, self.unary())
        return node

    def unary(self):
        if self.is_op("+", "-"):
            op = self.tok[1]
            self.advance()
            return ("neg" if op == "-" else "pos", self.unary())
        return self.power()

    def power(self):
        node = self.atom()
        if self.is_op("**"):
            pos = self.tok[2]
            self.advance()
            node = ("bin", "**", pos, node, self.unary())
        return node

    def atom(self):
        kind, val, pos = self.tok
        if kind == "num":
            self.advance()
            return ("num", val)
        if kind == "name":
            self.advance()
            if self.is_op("("):
                self.advance()
                args = []
                if not self.is_op(")"):
                    args.append(self.expr())
                    while self.is_op(","):
                        self.advance()
                        args.append(self.expr())
                self.expect(")")
                return ("call", val, pos, args)
            return ("var", val, pos)
        if self.is_op("("):
            self.advance()
            node = self.expr()
            self.expect(")")
            return node
        self.fail()


def _run(node, variables):
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "var":
        if node[1] not in variables:
            raise CalcError(f"unknown variable {node[1]!r}", node[2])
        return variables[node[1]]
    if kind == "neg":
        return -_run(node[1], variables)
    if kind == "pos":
        return +_run(node[1], variables)
    if kind == "call":
        _, name, pos, args = node
        if name not in _FUNCS:
            raise CalcError(f"unknown function {name!r}", pos)
        lo, hi, fn = _FUNCS[name]
        vals = [_run(a, variables) for a in args]
        if len(vals) < lo or (hi is not None and len(vals) > hi):
            raise CalcError(f"wrong number of arguments to {name}", pos)
        return fn(*vals)
    _, op, pos, ln, rn = node
    a = _run(ln, variables)
    b = _run(rn, variables)
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            return a / b
        if op == "//":
            return a // b
        if op == "%":
            return a % b
        r = a ** b
        if isinstance(r, complex):
            raise CalcError("power is not a real number", pos)
        return r
    except ZeroDivisionError:
        if op == "**":
            raise CalcError("zero to a negative power", pos)
        raise CalcError("division by zero", pos)
    except OverflowError:
        raise CalcError("result too large", pos)


def evaluate(expression, variables=None):
    tree = _Parser(expression).parse()
    return _run(tree, variables if variables is not None else {})
