def _tokens_at(text, i):
    """Return (kind, value, start, end) for the token starting at/after i."""
    n = len(text)
    while i < n and text[i] in " \\t":
        i += 1
    if i >= n:
        return ("end", None, n, n)
    c = text[i]
    if c.isascii() and c.isdigit() or (c == "." and i + 1 < n and text[i + 1].isascii() and text[i + 1].isdigit()):
        j = i
        while j < n and text[j].isascii() and text[j].isdigit():
            j += 1
        if j < n and text[j] == ".":
            j += 1
            while j < n and text[j].isascii() and text[j].isdigit():
                j += 1
            return ("num", float(text[i:j]), i, j)
        return ("num", int(text[i:j]), i, j)
    if c == "_" or (c.isascii() and c.isalpha()):
        j = i + 1
        while j < n and (text[j] == "_" or (text[j].isascii() and text[j].isalnum())):
            j += 1
        return ("name", text[i:j], i, j)
    if text.startswith("**", i):
        return ("op", "**", i, i + 2)
    if text.startswith("//", i):
        return ("op", "//", i, i + 2)
    if c in "+-*/%(),":
        return ("op", c, i, i + 1)
    raise CalcError(f"unexpected character {c!r}", i)


class _Parser:
    def __init__(self, text):
        self.text = text
        self.tok = _tokens_at(text, 0)

    def advance(self):
        t = self.tok
        self.tok = _tokens_at(self.text, t[3])
        return t

    def fail(self, t=None):
        t = t or self.tok
        if t[0] == "end":
            raise CalcError("unexpected end of expression", len(self.text))
        raise CalcError("unexpected token", t[2])

    def is_op(self, *ops):
        return self.tok[0] == "op" and self.tok[1] in ops

    def parse(self):
        node = self.expr()
        if self.tok[0] != "end":
            self.fail()
        return node

    def expr(self):
        node = self.term()
        while self.is_op("+", "-"):
            op = self.advance()
            node = ("bin", op[1], op[2], node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.is_op("*", "/", "//", "%"):
            op = self.advance()
            node = ("bin", op[1], op[2], node, self.unary())
        return node

    def unary(self):
        if self.is_op("+", "-"):
            op = self.advance()
            return ("un", op[1], self.unary())
        return self.power()

    def power(self):
        node = self.atom()
        if self.is_op("**"):
            op = self.advance()
            node = ("bin", "**", op[2], node, self.unary())
        return node

    def atom(self):
        t = self.tok
        if t[0] == "num":
            self.advance()
            return ("num", t[1])
        if t[0] == "name":
            self.advance()
            if self.is_op("("):
                self.advance()
                args = []
                if not self.is_op(")"):
                    args.append(self.expr())
                    while self.is_op(","):
                        self.advance()
                        args.append(self.expr())
                if not self.is_op(")"):
                    self.fail()
                self.advance()
                return ("call", t[1], t[2], args)
            return ("var", t[1], t[2])
        if self.is_op("("):
            self.advance()
            node = self.expr()
            if not self.is_op(")"):
                self.fail()
            self.advance()
            return node
        self.fail()


def _eval(node, variables):
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "var":
        if node[1] not in variables:
            raise CalcError(f"unknown variable {node[1]!r}", node[2])
        return variables[node[1]]
    if kind == "un":
        v = _eval(node[2], variables)
        return -v if node[1] == "-" else +v
    if kind == "call":
        _, name, pos, args = node
        if name not in _FUNCS:
            raise CalcError(f"unknown function {name!r}", pos)
        lo, hi = _FUNCS[name]
        if len(args) < lo or (hi is not None and len(args) > hi):
            raise CalcError(f"wrong number of arguments to {name}", pos)
        vals = [_eval(a, variables) for a in args]
        return {"min": min, "max": max, "abs": abs}[name](*vals)
    _, op, pos, left, right = node
    a = _eval(left, variables)
    b = _eval(right, variables)
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "**":
            r = a ** b
            if isinstance(r, complex):
                raise CalcError("power is not a real number", pos)
            return r
        if b == 0:
            raise CalcError("division by zero", pos)
        if op == "/":
            return a / b
        if op == "//":
            return a // b
        return a % b
    except ZeroDivisionError:
        raise CalcError("division by zero", pos) from None
    except OverflowError:
        raise CalcError("result too large", pos) from None


def evaluate(expression, variables=None):
    tree = _Parser(expression).parse()
    return _eval(tree, variables or {})
